 "title": "最長共通部分列のDP表",
 "prompt": "次の lcsTable は、文字列XとYの最長共通部分列の長さを動的計画法で求める表dpを作る。X=\"ABCD\"、Y=\"BACD\"として実行したとき、最後の行dp[4][0..4]はどれか。文字列の添字は1から始まる。",
 "code": [
  "○整数型の二次元配列: lcsTable(文字列型: X, 文字列型: Y)",
  "  dp[0..Xの長さ][0..Yの長さ]の全要素 ← 0",
  "  iを1からXの長さまで1ずつ増やす",
  "    jを1からYの長さまで1ずつ増やす",
  "      if (X[i] = Y[j])",
  "        dp[i][j] ← dp[i-1][j-1] + 1",
  "      else",
  "        dp[i][j] ← max(dp[i-1][j], dp[i][j-1])",
  "      endif",
  "    endfor",
  "  endfor",
  "  return dp"
 ],
