 "title": "ブルームフィルタのビット更新",
 "prompt": "次のrunは、長さ8のビット配列を使うブルームフィルタへ5, 12, 9を挿入した後、13と6を照会する。runが返す{bits, a, b}はどれか。bitsは添字0から7の順に左から並べた8文字、ANDは論理積を表す。",
