 "cat": "データ構造",
 "title": "スキップリストの探索経路",
 "prompt": "次のsearchPathは、3段のスキップリストでtargetを探索する。各レベルでは次のキーがtargetより小さい間だけ右へ移動し、等しければそのキーをpathへ追加して終了する。searchPath(40)の戻り値はどれか。HEADはpathへ追加しない。",
