 "cat": "セキュリティ",
 "title": "連鎖タグによるログ改ざん検出",
 "prompt": "監査ログの各レコードに、直前の正しいタグと現在のレコード値から計算した連鎖タグを保存する。次のverifyLogで、保存タグが初めて一致しない位置を検出したとき、返される{validCount, badIndex, expected, found}はどれか。modは剰余を表す。",
