 "cat": "アルゴリズム",
 "title": "Newton法による整数平方根",
 "prompt": "正の整数nの平方根以下で最大の整数を、整数演算だけで求める。次のintegerSqrtをn=200で実行したとき、返される{root, iterations}はどれか。divは小数部分を切り捨てる整数除算である。",
 "code": [
  "○組: integerSqrt(整数型: n)",
  "  x ← n, iterations ← 0",
  "  while (true)",
  "    iterations ← iterations + 1",
  "    q ← n div x",
  "    next ← (x + q) div 2",
  "    if (next ≧ x)",
  "      return {x, iterations}",
  "    endif",
  "    x ← next",
  "  endwhile"
 ],
