 "explain": "<p>切替え後、旧鍵K1を使えるのは時刻7までです。そのため時刻6のK1は受理されますが、時刻8のK1はUNKNOWN_KEYです。</p><p>時刻8のK2トークンは期限切れ、最後のK2トークンは署名不正です。よって<b>[ACCEPT,ACCEPT_PREVIOUS,UNKNOWN_KEY,EXPIRED,BAD_SIGNATURE]</b>になります。</p>",
