 "prompt": "次のbinaryGcdは、偶数なら2で割る操作と減算を用いて最大公約数を求める。binaryGcd(48,18)の戻り値はどれか。a,bは正の整数とする。",
 "code": [
  "○整数型: binaryGcd(整数型: a, b)",
  "  factor ← 1",
  "  while (aが偶数 and bが偶数)",
  "    a ← a ÷ 2, b ← b ÷ 2, factor ← factor × 2",
  "  endwhile",
  "  while (aが偶数)",
  "    a ← a ÷ 2",
  "  endwhile",
  "  while (b ≠ 0)",
  "    while (bが偶数)",
  "      b ← b ÷ 2",
  "    endwhile",
  "    if (a ＞ b)",
  "      aとbを交換する",
  "    endif",
  "    b ← b － a",
  "  endwhile",
  "  return factor × a"
 ],
