 "cat": "プログラミング",
 "title": "8ビット飽和加算の逐次処理",
 "prompt": "次のsaturatingSumは、各加算の直後に値を8ビット符号付き整数の範囲-128〜127へ収める。saturatingSum(values)の戻り値はどれか。clampsは上限又は下限への補正回数を表す。",
