  "    if (i ＜ chainの要素数 and c.issuer ≠ chain[i＋1].subject)",
  "      return \"発行者不一致:\" ＋ c.subject",
  "    endif",
  "  endfor",
  "  root ← chain[chainの要素数]",
  "  if (root.subject が trustedRoots に含まれない)",
