 "prompt": "次のeditDistanceは、文字列XをYへ変換するための挿入・削除・置換の最小回数を動的計画法で求める。各操作のコストは1で、同じ文字を対応させるコストは0とする。editDistance(\"CAT\",\"CUTS\")の戻り値はどれか。",
